def split_intervals(g, marker):
 runs=defaultdict(list)
 for r,row in enumerate(g):
  for c,x in enumerate(row):
   if x==marker: runs[c-r].append(r+c)
 res={}
 for d,us in runs.items():
  us=sorted(us); chunks=[]
  for u in us:
   if not chunks or u>chunks[-1][-1]+2: chunks.append([u])
   else: chunks[-1].append(u)
  res[d]=[(ch[0],ch[-1]) for ch in chunks]
 return res
